class DifficultyConfig { final String id, label; final double enemyHealth, enemyDamage, spawnRate, rewardMultiplier; final int maxConcurrentEnemies; const DifficultyConfig(this.id,this.label,{required this.enemyHealth,required this.enemyDamage,required this.spawnRate,required this.rewardMultiplier,required this.maxConcurrentEnemies}); static const easy=DifficultyConfig('easy','Лёгкая',enemyHealth:.75,enemyDamage:.7,spawnRate:.8,rewardMultiplier:.8,maxConcurrentEnemies:12); static const normal=DifficultyConfig('normal','Нормальная',enemyHealth:1,enemyDamage:1,spawnRate:1,rewardMultiplier:1,maxConcurrentEnemies:18); static const hard=DifficultyConfig('hard','Тяжёлая',enemyHealth:1.45,enemyDamage:1.35,spawnRate:1.2,rewardMultiplier:1.4,maxConcurrentEnemies:24); static const hell=DifficultyConfig('hell','Ад',enemyHealth:1.9,enemyDamage:1.7,spawnRate:1.4,rewardMultiplier:2,maxConcurrentEnemies:30); static DifficultyConfig byId(String id) => switch(id){'easy'=>easy,'hard'=>hard,'hell'=>hell,_=>normal}; }
